export const mePartialUpdate = <ThrowOnError extends boolean = false>(
  options?: Options<MePartialUpdateData, ThrowOnError>,
) =>
  (options?.client ?? client).patch<MePartialUpdateResponses, MePartialUpdateErrors, ThrowOnError>({
    security: [
      { scheme: 'basic', type: 'http' },
      { name: 'Authorization', type: 'apiKey' },
    ],
    url: '/me/',
    ...options,
    headers: {
      'Content-Type': 'application/json',
      ...options?.headers,
    },
  });

/**
 * ## View current user's email
 *
 */
export const meEmailsList = <ThrowOnError extends boolean = false>(
  options?: Options<MeEmailsListData, ThrowOnError>,
) =>
  (options?.client ?? client).get<MeEmailsListResponses, MeEmailsListErrors, ThrowOnError>({
    security: [
      { scheme: 'basic', type: 'http' },
      { name: 'Authorization', type: 'apiKey' },
    ],
    url: '/me/emails/',
    ...options,
  });

/**
 * ## Set a new email
 *
 * The new email will be unverified and replace existing unverified, non-primary emails.
 * New email is not usable until verified.
 *
 */
export const meEmailsCreate = <ThrowOnError extends boolean = false>(
  options: Options<MeEmailsCreateData, ThrowOnError>,
) =>
  (options.client ?? client).post<MeEmailsCreateResponses, MeEmailsCreateErrors, ThrowOnError>({
    security: [
      { scheme: 'basic', type: 'http' },
      { name: 'Authorization', type: 'apiKey' },
    ],
    url: '/me/emails/',
    ...options,
    headers: {
      'Content-Type': 'application/json',
      ...options.headers,
    },
  });

